/**
 * Expo config plugin that injects a release signing config into the
 * Gradle build generated by `expo prebuild`.
 *
 * Android's default Expo template signs *release* builds with the debug
 * keystore. This plugin adds a real `release` signing config that reads its
 * credentials from Gradle project properties, and points the release build
 * type at it — but only when those properties are present. That keeps local
 * `expo run:android` / debug builds working unchanged while letting CI pass
 * the real keystore via `-P` flags.
 *
 * Properties expected (passed by the GitHub Actions workflow):
 *   MYAPP_RELEASE_STORE_FILE      e.g. release.keystore (relative to android/app)
 *   MYAPP_RELEASE_STORE_PASSWORD
 *   MYAPP_RELEASE_KEY_ALIAS
 *   MYAPP_RELEASE_KEY_PASSWORD
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const RELEASE_SIGNING_CONFIG = `        release {
            if (project.hasProperty('MYAPP_RELEASE_STORE_FILE')) {
                storeFile file(MYAPP_RELEASE_STORE_FILE)
                storePassword MYAPP_RELEASE_STORE_PASSWORD
                keyAlias MYAPP_RELEASE_KEY_ALIAS
                keyPassword MYAPP_RELEASE_KEY_PASSWORD
            }
        }`;

function addReleaseSigning(contents) {
  if (contents.includes('MYAPP_RELEASE_STORE_FILE')) {
    // Already patched (idempotent).
    return contents;
  }

  // 1. Add a `release` block to `signingConfigs`, right after the debug block.
  const debugSigningBlock = /(signingConfigs\s*\{[\s\S]*?keyPassword\s+'android'\s*\n\s*\})/;
  if (!debugSigningBlock.test(contents)) {
    throw new Error(
      'withAndroidSigning: could not find the debug signingConfig block to patch. ' +
        'The Expo Android template may have changed.'
    );
  }
  contents = contents.replace(debugSigningBlock, `$1\n${RELEASE_SIGNING_CONFIG}`);

  // 2. Point the release build type at the release config when available,
  //    falling back to debug otherwise. The "Caution!" comment is unique to
  //    the release build type, so this targets the correct line.
  const releaseBuildTypeSigning = /(\/\/ Caution! In production[\s\S]*?\n\s*)signingConfig signingConfigs\.debug/;
  if (!releaseBuildTypeSigning.test(contents)) {
    throw new Error(
      'withAndroidSigning: could not find the release buildType signingConfig to patch.'
    );
  }
  contents = contents.replace(
    releaseBuildTypeSigning,
    `$1signingConfig project.hasProperty('MYAPP_RELEASE_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`
  );

  return contents;
}

module.exports = function withAndroidSigning(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy') {
      throw new Error(
        'withAndroidSigning: expected a Groovy build.gradle but found ' +
          config.modResults.language
      );
    }
    config.modResults.contents = addReleaseSigning(config.modResults.contents);
    return config;
  });
};
